// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Ensure the caller is the owner for the allowance call (no additional setup needed as constructor set _owner = address(this))
        // Call allowance(address,address) to trigger the diverging logic (in reference, it just reads; in bug, changeOwner might have been called? Actually the bug is in changeOwner, but we need to trigger changeOwner. 
        // Since the test must end with allowance and the bug changes _owner only when changeOwner is called, we need to call changeOwner first.
        // However the requirement says "driven through the public/external entry allowance(address,address)" - the divergence is observed after allowance completes. 
        // The difference: after allowance call, _owner differs. To achieve this, we first call changeOwner which in the buggy version sets _owner to address(0).
        vm.prank(address(this)); // owner
        c.changeOwner(address(1)); // In reference, _owner becomes address(1); in bug, _owner becomes address(0)
        // Now call allowance to observe the divergence
        c.allowance(address(this), address(this));
        // Assert: reference has _owner = address(1), bug has _owner = address(0)
        assertTrue(c.owner() != address(0));
    }
}

