import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // The mutant breaks changeOwner to always set _owner = address(0)
        // The constructor sets _owner = address(this). We call allowance which triggers _transfer logic
        // that eventually calls changeOwner with address(0) in the buggy version.

        // Setup: authorize the caller as a role to enable the reward path in _transfer
        // The _allowedRoles mapping is private (no getter) - we cannot set it directly.
        // Instead, we use the fact that the constructor creates the uniswap pair, and the
        // changeOwner bug is triggered by calling allowance which involves _transfer logic
        // that may call changeOwner.

        // Since the contract uses _allowedRoles internally and we cannot set it, we need
        // another approach: observe that the constructor calls _owner = payable(msg.sender)
        // but the changeOwner bug in the reference does nothing special.

        // Concrete scenario: call allowance(address,address) - this does NOT change the owner.
        // The buggy version's changeOwner is not called by allowance, so both versions
        // should behave the same. We need to find a scenario where changeOwner is actually invoked.

        // Actually, re-reading the code: changeOwner is only called directly via the public function.
        // The _transfer function does NOT call changeOwner. So allowance won't trigger the bug.
        // The difference must be observed after someone calls changeOwner with wrong parameter.

        // Concrete scenario: The owner (address(this)) calls changeOwner with some address.
        // Reference: sets _owner = newOwner
        // Buggy: sets _owner = address(0)

        // So we call changeOwner(address(this)) which should keep owner as address(this)
        // in reference, but sets owner to address(0) in buggy.
        c.changeOwner(address(this));

