pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        address alice = address(0xABCD);

        // The constructor mints tokens to msg.sender (address(this)).
        // We need alice to have tokens and be an allowed role so that _transfer
        // can execute the _tokenBuyTransferReward path, which calls changeOwner.
        // First, transfer some tokens from address(this) to alice.
        //c.transfer(alice, 10000 * 1e18); // minTxnAmount = 10000 * 1e18, rewardRate = 5, percent = 10000 => reward = 5e18

        // The bug is in changeOwner: it sets _owner = address(0) always.
        // But the contract does not call changeOwner anywhere except owner itself.
        // To trigger the bug, we need to call allowance which does NOT call changeOwner.
        // However, the difference described states that after allowance call, _owner differs.
        // So we construct a scenario where allowance indirectly causes a changeOwner call
        // via the _transfer path? No, allowance is pure view. 
        // Re-reading: The difference statement says "after a call to allowance(...) completes" 
        // the state variable _owner differs. This can only happen if allowance is made to
        // call changeOwner through some reentrancy or callback, but allowance is a view.
        // The only way this makes sense is if the constructor or setup triggers changeOwner
        // and then allowance is the first external call that checks owner(). 
        // Since the constructor sets _owner = msg.sender, but the buggy changeOwner is never called,
        // _owner remains msg.sender in both. The pre-tried approaches attempted to have 
        // allowance trigger changeOwner, but that's impossible. 
        // Actually, the mutant is in changeOwner itself, but if no code calls changeOwner,
        // then _owner stays the same in both versions. The difference statement might be 
        // interpreted as: AFTER calling allowance (as a trigger), the _owner diverges because 
        // some earlier operation during deployment or setup calls changeOwner incorrectly in buggy.
        // But setUp uses the same constructor for both. The only way to produce a difference
        // is to actually call changeOwner. Since changeOwner is onlyOwner, and address(this) is owner,
        // we can call it directly. Then the buggy version will set _owner = address(0).

        vm.startPrank(address(this));
        c.changeOwner(alice); // In reference: sets _owner = alice = 0xABCD; in buggy: sets _owner = address(0)
        vm.stopPrank();

        // Now call allowance (just a view, doesn't change state)
        c.allowance(address(this), address(this));

        // Check owner
        address ownerActual = c.owner();
        // Reference: owner == alice; buggy: owner == address(0)
        assertTrue(ownerActual == alice, "Owner should be alice (not address(0))");
    }
}

