// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // The test contract (address(this)) is the owner after deployment.
        // In the buggy version, the onlyOwner modifier always reverts, so changeOwner will always revert.
        // But the test contract itself is the caller of changeOwner, and the test contract is the owner.
        // The bug: modifier requires(false), so even the owner cannot call changeOwner.
        // So we need a different scenario: after allowance is called by a non-owner, the owner variable should remain unchanged.
        // But to trigger a difference, we rely on the fact that in the reference version, the owner can be changed.
        // We'll change the owner to address(0) in the reference, then check that after allowance, the owner differs.
        // Sequence: 
        // 1. Owner (address(this)) calls changeOwner(address(0)) — succeeds in reference, reverts in buggy.
        // 2. Then call allowance(address, address) with some arbitrary addresses.
        // 3. Check _owner: in reference it's address(0), in buggy it's still address(this).
        // But this tests the changeOwner function directly, not allowance's effect.
        // The given difference says after a call to allowance(...) completes, _owner differs.
        // So we need allowance to somehow affect _owner in the buggy version.
        // In the buggy version, the onlyOwner modifier is broken and reverts always, but that doesn't change _owner.
        // Let's re-analyze: The bug is only in onlyOwner modifier. The only function that changes _owner is changeOwner.
        // But changeOwner is protected by onlyOwner, so in buggy version it always reverts.
        // So _owner should never change in buggy version. In reference, _owner can be changed by owner.
        // The difference: after a call, reference's _owner could be different from buggy's _owner if in reference we changed it.
        // But the scenario must be: after allowance call, the state differs.
        // Possibly the buggy version has a different vulnerability: if the modifier is false, then any call to a function with that modifier reverts.
        // But allowance does not have onlyOwner, so it doesn't revert.
        // The only way _owner differs after allowance is if allowance itself changes _owner (it doesn't) or if some internal function called by allowance changes it.
        // In the code, allowance is a simple view function that reads a mapping. No state change.
        // So this is a trick: the difference is that in reference, the owner can be changed BEFORE allowance, and after allowance the owner state is different.
        // But the wording says "after a call to allowance(...) completes, the value of state variable _owner differs".
        // Possibly we need to call changeOwner BEFORE, then allowance, then check _owner.
        // But that would mean allowance doesn't actually change _owner; it's just that the state is different due to prior call.
        // The difference: In reference, changeOwner succeeded, so _owner changed. In buggy, changeOwner reverted, so _owner stayed same.
        // Then allowance doesn't affect it, but after those two operations, _owner differs.
        // So the assertion: c._owner() should be address(0) for reference and address(this) for buggy.
        // But the buggy version reverts on changeOwner, so we need to wrap that in try/catch or accept revert.
        // The test must call allowance after changeOwner (whether it reverts or not).
        // Let's implement this:
        // First, try to change owner to a new address (e.g., address(0)).
        // In reference, this succeeds, so _owner becomes address(0).
        // In buggy, this reverts, so _owner stays address(this).
        // Then call allowance(address, address) with arbitrary values.
        // Then check c._owner(): it will be address(0) in reference, address(this) in buggy.
        // But the catch: in the buggy version, changeOwner reverts, so the test must handle that the previous call failed.
        // We'll use vm.prank to set caller as owner (address(this)) and call changeOwner, which reverts in buggy.
        // The revert doesn't stop the test? Actually, if we don't wrap in try/catch, a revert fails the whole test.
        // So we need to allow the revert to happen but still continue the test.
        // We can use vm.expectRevert but cheatcodes are restricted. So we must use try/catch.
        // But try/catch is only for external calls. c.changeOwner is an external call.
        // We'll wrap in try/catch.
        bool changeSucceeded;
        vm.prank(address(this));
        try c.changeOwner(address(0)) {
            changeSucceeded = true;
        } catch {
            changeSucceeded = false;
        }
        // Now call allowance
        c.allowance(address(0), address(0));
        // Now assert: in reference, changeSucceeded is true, so _owner is address(0); in buggy, false, so _owner is address(this).
        assertTrue(changeSucceeded ? c._owner() == address(0) : c._owner() == address(this));
        // But this assertion is tautological; it always holds because it depends on changeSucceeded.
        // We need a single concrete fact that holds for reference and fails for buggy.
        // The concrete fact: c._owner() == address(0) (i.e., the owner was changed).
        // In reference, changeSucceeded is true, so _owner = address(0).
        // In buggy, changeSucceeded is false, so _owner stays address(this) (which is not address(0)).
        // So assertTrue(c._owner() == address(0));
        // This will pass in reference (since changeOwner worked) and fail in buggy (since changeOwner reverted).
        assertTrue(c._owner() == address(0));
    }
}

