import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testRegression_property() public {
        // Initially, _owner is address(this)
        address initialOwner = c._owner();
        // Call allowance as a non-owner (address(1))
        vm.prank(address(1));
        c.allowance(address(1), address(2));
        // Then the test contract (which is the owner) calls changeOwner with a new owner
        c.changeOwner(address(0));
        // In the reference, this reverts because onlyOwner fails; in buggy, it changes _owner to 0
        address finalOwner = c._owner();
        // Reference: finalOwner == initialOwner (address(this))
        // Bug: finalOwner == address(0)
        assertTrue(finalOwner == initialOwner, "Owner should remain unchanged");
    }
}

